                        "method":  "1. Heat milk in rondo till it reaches a temperature of 185 f.\n2. Cut heat and add vinegar, then give 1 good stir.\n3. Keep milk at 185 as best you can for 20 min on low heat. you may have to turn off the heat to regulate.\n4. After 20 min strain through a fine mesh sieve, reserving 1 qt of the liquid whey.\n5. Turn strained cheese into a mixing bowl and ladle whey back into the cheese until it reaches a moist creamy consistency.\n6. Cool on rack.\n7. Date and store in green lid cambro in reach in cooler",
