                        "ingredients":  "1 Burger Patty 8oz split in half\n2 slice Cheese american\n1 tbsp Dijonaise\n4 Pickles\nPomme Frites\n1 slice Bacon possible addon\n1 Egg possible addon, fried over easy\n1 ramekin Sriracha Mayo",
