                        "notes":  "N/A",
                        "ingredients":  "2 cup Tahini\n1/2 cup Lemon, juice about 4 lemons\n4 Garlic, cloves minced\n1/2 cup Olive Oil extra-virgin\n1/4 cup Water\n2 tsp Ground Cumin\n1 tsp Smoked Paprika\nto taste Salt\n1/4 cup Toasted Sesame Seeds and charred\nas needed Water",
