                        "method":  "1. Combine the brine ingredients: In a large pot, combine the water, salt, and sugar. Warm over medium heat, stirring, until the salt and sugar dissolve completely.\n2. Add citrus and herbs: Remove the pot from the heat. Add the lemon, lime, and orange zest and juice, along with the garlic, peppercorns, thyme, rosemary, parsley, and bay leaves.\n3. Cool the brine: Allow the brine to cool to room temperature. To speed up the process, you can place the pot in an ice bath.\n4. Brine the chicken: Once the brine is completely cool, add the chicken pieces ensuring they are fully submerged. Cover and refrigerate for 12 to 24 hours, depending on the size of the chicken pieces.\n5. Prepare for cooking: After brining, remove the chicken from the brine, rinse under cold water, and pat dry with paper towels.",
