                        "method":  "1. Blend all in robo coop till it forms together in a ball.\n2. Wrap that ball of dough in plastic wrap and let it rest for 30 min.\n3. Assemble machine while you wait.\n4. Divide ball in 2, wrap other half while you work with one.\n5. Flatten first ball with hands till it can fit through the 1 setting on the machine.\n6. With machine running, run pasta through machine, adding flour if it sticks.\n7. Fold dough in 3 like a letter\n8. Run through machine again and repeat one more time.\n9. Run dough through the machine on each setting stopping at setting 6.\n10. Around setting 3 you will have to cut pasta in half\n11. 1 portion of pasta is 1 half of your sheet, each pasta dough ball makes 4 portions\n12. After setting 6, heavily flour sheet and roll into a neat roll.\n13. Cut pasta into thick ribbons\n14. Gently stack and bundle the pasta on a sheet tray with parchment paper\n15. Bag in pint bag and freeze until ready to use",
