                        "method":  "1. Finely chop all ingredients (use a mandolin if needed)\n2. Cover all ingredients in a large pot with 8 gallons of water\n3. Bring to a simmer/reduce and allow to cook for 2 hours approx 6 gallons or 24 quarts\n4. Strain vegetable matter out of stock\n5. Date and store in walk in cooler",
