                        "notes":  "N/A",
                        "ingredients":  "2 qt Spent Chilis From Hot Sauce Chilies, finely diced\n2 cup Garlic, cloves Garlic minced\n1 ramekin Parsley, chopped Fresh\n1 Lemon, zest about 1 lemon\n1 Olive Oil\nto taste Salt And Pepper",
