                        "notes":  "",
                        "ingredients":  "1/2 gallon Buttermilk\n1/2 cup Salt And Pepper mix\n2 cup Spent Chilis From Hot Sauce spent chili from",
                        "name":  "Buttermilk Marinade For Hot Chicken \u0027old\u0027",
