                        "ingredients":  "2 qt Mayo\n1 pint Lime, juice 1/2 qt\n1 cup Dijon Mustard 1/4 qt\n1/2 cup Ground Black Pepper\n1 cup Sugar\n3 bunch Cilantro, chopped\n1/4 cup Ginger Dried",
